#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n),res(n,-1);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
vector<int>st;
for(int i=0;i<n;++i){
while(!st.empty()&&a[st.back()]>a[i]){res[st.back()]=a[i];st.pop_back();}
st.push_back(i);}
for(int i=0;i<n;++i){if(i)printf(" ");printf("%lld",res[i]);}
printf("\n");return 0;}

